// ACCA FA 入門 — app logic (vanilla JS, no build step).
// Content: content/index.js lists unit files (window.ACCA_UNIT_FILES, generated by
// build-manifest.js). Each unit file pushes one object onto window.ACCA_UNITS.
// A test page may point at another list with ?manifest=<relative path>.js.
(function () {
  'use strict';

  var app = document.getElementById('app');

  // ---------- content loading ----------
  var SAFE_PATH = /^(?!\/)(?!.*\.\.)[\w\-./]+\.js$/;
  function manifestPath() {
    var m = null;
    try { m = new URLSearchParams(location.search).get('manifest'); } catch (e) { m = null; }
    return m && SAFE_PATH.test(m) ? m : 'content/index.js';
  }
  function addScript(src, ordered) {
    return new Promise(function (resolve) {
      var s = document.createElement('script');
      s.src = src;
      if (ordered) s.async = false; // parallel download, execution in insertion order
      s.onload = function () { resolve(true); };
      s.onerror = function () { resolve(false); };
      document.head.appendChild(s);
    });
  }
  function fatal(msg) {
    app.innerHTML = '<p class="fatal">' + msg + '</p>';
  }

  var mPath = manifestPath();
  addScript(mPath, false).then(function (ok) {
    var list = window.ACCA_UNIT_FILES;
    if (!ok || !Array.isArray(list)) {
      fatal('教材の一覧（' + mPath.replace(/[<>&"']/g, '') + '）を読み込めませんでした。<br>node build-manifest.js を実行してから開き直してください。');
      return null;
    }
    list = list.filter(function (f) { return typeof f === 'string' && SAFE_PATH.test(f); });
    return Promise.all(list.map(function (f) { return addScript(f, true); })).then(function (res) {
      var failed = list.filter(function (_, i) { return !res[i]; });
      return failed;
    });
  }).then(function (failed) {
    if (failed === null || failed === undefined) return;
    start(buildContent(window.ACCA_UNITS), failed);
  });

  function buildContent(units) {
    units = (Array.isArray(units) ? units : []).filter(function (u) {
      return u && typeof u === 'object' && Array.isArray(u.lessons);
    });
    units = units.map(function (u, i) { return { u: u, i: i }; }).sort(function (a, b) {
      var ua = Number(a.u.unit), ub = Number(b.u.unit);
      if (!isFinite(ua)) ua = 1e9;
      if (!isFinite(ub)) ub = 1e9;
      return ua - ub || a.i - b.i;
    }).map(function (x) { return x.u; });
    var lessons = [], cards = [], seenL = {}, seenC = {}, parts = [], partByKey = {};
    units.forEach(function (u) {
      var key = String(u.part != null ? u.part : '?');
      var part = partByKey[key];
      if (!part) {
        part = { key: key, part: u.part, title: u.partTitle || '', lessons: [] };
        partByKey[key] = part;
        parts.push(part);
      } else if (!part.title && u.partTitle) part.title = u.partTitle;
      u.lessons.forEach(function (l) {
        if (!l || typeof l.id !== 'string' || seenL[l.id]) return;
        seenL[l.id] = true;
        lessons.push(l);
        part.lessons.push(l);
      });
      (Array.isArray(u.cards) ? u.cards : []).forEach(function (c) {
        if (!c || typeof c.id !== 'string' || seenC[c.id]) return;
        seenC[c.id] = true;
        cards.push(c);
      });
    });
    parts = parts.filter(function (p) { return p.lessons.length; });
    return { lessons: lessons, cards: cards, parts: parts };
  }

  function start(C, failedFiles) {
    window.ACCA_APP = C; // for tests and debugging

    var KEY = 'acca-study-v1';
    var INTERVALS = [1, 3, 7, 30, 90];
    var cardById = {};
    C.cards.forEach(function (c) { cardById[c.id] = c; });
    var partOf = {};
    C.parts.forEach(function (p) { p.lessons.forEach(function (l) { partOf[l.id] = p; }); });

    // ---------- dates (local calendar) ----------
    function pad(n) { return (n < 10 ? '0' : '') + n; }
    function fmt(d) { return d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate()); }
    function today() { return fmt(new Date()); }
    function parse(ymd) { var p = ymd.split('-').map(Number); return new Date(p[0], p[1] - 1, p[2]); }
    function addDays(ymd, n) { var d = parse(ymd); return fmt(new Date(d.getFullYear(), d.getMonth(), d.getDate() + n)); }
    function mdLabel(ymd) { var d = parse(ymd); return (d.getMonth() + 1) + '月' + d.getDate() + '日'; }
    function longDate(ymd) { var d = parse(ymd); return mdLabel(ymd) + '（' + '日月火水木金土'.charAt(d.getDay()) + '）'; }
    function dueLabel(ymd) {
      var t = today();
      if (ymd <= t) return '今日';
      if (ymd === addDays(t, 1)) return '明日（' + mdLabel(ymd) + '）';
      return mdLabel(ymd);
    }

    // ---------- persistence (shape unchanged since v1: { completed, cards }) ----------
    var DATE_RE = /^\d{4}-\d{2}-\d{2}$/;
    function load() {
      var s = null;
      try { s = JSON.parse(localStorage.getItem(KEY)); } catch (e) { s = null; }
      if (!s || typeof s !== 'object' || Array.isArray(s)) s = {};
      if (!s.completed || typeof s.completed !== 'object' || Array.isArray(s.completed)) s.completed = {};
      if (!s.cards || typeof s.cards !== 'object' || Array.isArray(s.cards)) s.cards = {};
      Object.keys(s.cards).forEach(function (id) {
        var c = s.cards[id];
        if (!c || typeof c !== 'object' || typeof c.due !== 'string' || !DATE_RE.test(c.due)) { delete s.cards[id]; return; }
        var st = Math.floor(Number(c.step));
        c.step = isFinite(st) ? Math.max(0, Math.min(INTERVALS.length - 1, st)) : 0;
      });
      return { completed: s.completed, cards: s.cards };
    }
    var state = load();
    function save() {
      try { localStorage.setItem(KEY, JSON.stringify(state)); } catch (e) { /* storage unavailable */ }
    }

    // ---------- scheduling ----------
    function rate(id, remembered) {
      var c = state.cards[id] || { step: 0, due: today() };
      if (remembered) {
        c.due = addDays(today(), INTERVALS[c.step]);
        c.step = Math.min(c.step + 1, INTERVALS.length - 1);
      } else {
        c.step = 0;
        c.due = addDays(today(), 1);
      }
      state.cards[id] = { step: c.step, due: c.due };
      save();
    }
    function byDue(a, b) {
      var da = state.cards[a].due, db = state.cards[b].due;
      return da < db ? -1 : da > db ? 1 : 0;
    }
    function deckIds() {
      return C.cards.filter(function (c) { return state.cards[c.id]; }).map(function (c) { return c.id; });
    }
    function dueIds() {
      var t = today();
      return deckIds().filter(function (id) { return state.cards[id].due <= t; });
    }

    // ---------- helpers ----------
    function esc(s) {
      return String(s == null ? '' : s).replace(/[&<>"']/g, function (ch) {
        return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[ch];
      });
    }
    function langAttr(s) { return /^[\x20-\x7E]+$/.test(String(s)) ? ' lang="en"' : ''; }
    var ICON_CLOSE = '<svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round"><path d="M6 6l12 12M18 6L6 18"/></svg>';
    var ICON_OK = '<svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="2.6" stroke-linecap="round" stroke-linejoin="round"><path d="M5 12.5l4.5 4.5L19 7.5"/></svg>';
    var ICON_NG = '<svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="2.6" stroke-linecap="round"><path d="M7 7l10 10M17 7L7 17"/></svg>';
    var ICON_WARN = '<svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 3.5L2.8 19.5h18.4z"/><path d="M12 10v4.2M12 17v.2"/></svg>';
    var ICON_TIP = '<svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M9 18h6M10 21h4"/><path d="M12 3a6 6 0 0 0-3.6 10.8c.7.6 1.1 1.4 1.1 2.2h5c0-.8.4-1.6 1.1-2.2A6 6 0 0 0 12 3z"/></svg>';
    var ICON_CHEVRON = '<svg class="chev" viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M6 9l6 6 6-6"/></svg>';
    function lessonNo(lesson) {
      if (lesson && lesson.no !== undefined && lesson.no !== null && String(lesson.no) !== '') return String(lesson.no);
      return String(C.lessons.indexOf(lesson) + 1);
    }
    function examTag(lesson) {
      if (lesson.exam === 'fa') return '<span class="tag">FAのみ</span>';
      if (lesson.exam === 'k1') return '<span class="tag">K1のみ</span>';
      return '';
    }
    function partLabel(p) {
      return (p.part != null && p.part !== '' ? '第' + esc(p.part) + '部' : '');
    }
    function $(sel) { return app.querySelector(sel); }
    function focusEl(el) { if (el) { try { el.focus({ preventScroll: true }); } catch (e) { el.focus(); } } }
    function focusTitle() {
      var h = app.querySelector('h1');
      if (h) { h.setAttribute('tabindex', '-1'); focusEl(h); }
    }

    // ---------- numbers (quiz) ----------
    function parseNumber(raw, unit) {
      var s = String(raw == null ? '' : raw);
      if (s.normalize) s = s.normalize('NFKC');
      if (unit) s = s.split(unit).join('');
      s = s.replace(/[\s,$£€¥円%日]/g, '').replace(/[−‒–—―]/g, '-');
      var neg = false;
      if (/^\(.+\)$/.test(s)) { neg = true; s = s.slice(1, -1); }
      if (!/^[-+]?(\d+\.?\d*|\.\d+)$/.test(s)) return NaN;
      var n = Number(s);
      return neg ? -n : n;
    }
    function fmtNumber(n, unit) {
      var s = Math.abs(n).toLocaleString('en-US', { maximumFractionDigits: 6 });
      var sign = n < 0 ? '-' : '';
      if (unit === '$') return sign + '$' + s;
      return sign + s + (unit || '');
    }
    function isCorrect(q, ans) {
      if (ans === undefined) return false;
      if (q.type === 'number') return typeof ans === 'number' && Math.abs(ans - Number(q.answer)) <= 0.005 + 1e-9;
      return ans === q.answer;
    }

    // ---------- view state & history ----------
    var view = 'home';
    var flow = null;
    var review = null;
    // A history entry is pushed when a lesson or review opens, so the phone's back
    // gesture returns to Home instead of leaving the app.
    var pushed = false;       // our entry is on top of the history stack
    var ignorePop = false;    // the next popstate comes from our own history.back()
    var pendingPush = false;  // a push requested while that back() is still in flight
    var firstRender = true;
    var openParts = {};       // part key -> open/closed chosen by the user this session

    function doPush() {
      try { history.pushState({ acca: 1 }, ''); pushed = true; } catch (e) { pushed = false; }
    }
    function enterSubview() {
      if (pushed) return;
      if (ignorePop) { pendingPush = true; return; }
      doPush();
    }
    function goHome() {
      if (pushed) {
        pushed = false;
        ignorePop = true;
        try { history.back(); } catch (e) { ignorePop = false; }
      }
      pendingPush = false;
      renderHome();
    }
    window.addEventListener('popstate', function () {
      if (ignorePop) {
        ignorePop = false;
        if (pendingPush) { pendingPush = false; doPush(); }
        return;
      }
      pushed = false;
      if (view !== 'home') renderHome();
    });

    // ---------- home ----------
    function lessonRowHTML(l, next) {
      var done = !!state.completed[l.id];
      var meta = '<span class="nw">' + esc(l.minutes) + '分</span>' + examTag(l);
      if (done) {
        var dues = C.cards.filter(function (c) { return c.lesson === l.id && state.cards[c.id]; })
          .map(function (c) { return state.cards[c.id].due; }).sort();
        if (dues.length) meta += '<span class="nw review-line">次の復習 ' + esc(dueLabel(dues[0])) + '</span>';
      }
      var no = lessonNo(l);
      var cls = 'lesson-row' + (done ? ' is-done' : '') + (next === l ? ' is-next' : '');
      return '<li><button type="button" class="' + cls + '" data-lesson="' + esc(l.id) + '">' +
        '<span class="num' + (no.length >= 3 ? ' long' : '') + '" aria-hidden="true">' + esc(no) + '</span>' +
        '<span class="row-main"><span class="row-title"><span class="sr-only">レッスン ' + esc(no) + ' </span>' + esc(l.title) + '</span>' +
        '<span class="row-meta">' + meta + '</span></span>' +
        '<span class="badge">' + (done ? '完了' : '未学習') + '</span>' +
        '</button></li>';
    }

    function renderHome() {
      view = 'home'; flow = null; review = null;
      var t = today();
      var deck = deckIds();
      var due = dueIds();
      var next = null, doneAll = 0;
      for (var i = 0; i < C.lessons.length; i++) {
        if (state.completed[C.lessons[i].id]) doneAll++;
        else if (!next) next = C.lessons[i];
      }

      var h = '<main class="page home">';
      h += '<header class="home-head"><h1 class="app-title">ACCA FA 入門</h1><p class="today">' + esc(longDate(t)) +
        (C.lessons.length ? '<span class="overall">完了 ' + doneAll + ' / ' + C.lessons.length + '</span>' : '') + '</p></header>';

      if (failedFiles && failedFiles.length) {
        h += '<p class="load-warn" role="status">読み込めなかった教材ファイルがあります: ' + esc(failedFiles.join(', ')) + '</p>';
      }

      h += '<section class="review-box" aria-label="復習">';
      if (due.length) {
        h += '<button type="button" class="btn btn-primary btn-big" data-act="review-due">今日の復習（' + due.length + '枚）</button>';
      } else {
        h += '<p class="review-done">今日の復習は終わりました</p>';
        if (deck.length) {
          h += '<button type="button" class="btn btn-secondary" data-act="review-all">全部のカードを復習する</button>';
        } else {
          h += '<p class="note">レッスンを終えると、ここに復習カードが追加されます。</p>';
        }
      }
      h += '</section>';

      h += '<section class="block" aria-labelledby="next-label"><h2 class="label" id="next-label">次のレッスン</h2>';
      if (next) {
        var np = partOf[next.id];
        h += '<button type="button" class="next-card" data-lesson="' + esc(next.id) + '">' +
          '<span class="next-num">レッスン ' + esc(lessonNo(next)) + (np && np.title ? '<span class="next-part"> ・ ' + esc(np.title) + '</span>' : '') + '</span>' +
          '<span class="next-title">' + esc(next.title) + '</span>' +
          '<span class="next-goal">' + esc(next.goal) + '</span>' +
          '<span class="next-foot"><span class="next-meta">' + esc(next.minutes) + '分' + examTag(next) + '</span><span class="next-go">はじめる</span></span>' +
          '</button>';
      } else if (C.lessons.length) {
        h += '<p class="all-done">すべてのレッスンを完了しました。復習を続けましょう。</p>';
      } else {
        h += '<p class="all-done">教材がまだありません。</p>';
      }
      h += '</section>';

      if (C.parts.length) {
        var nextPart = next ? partOf[next.id] : null;
        h += '<section class="block" aria-labelledby="list-label"><h2 class="label" id="list-label">レッスン一覧</h2><div class="parts">';
        C.parts.forEach(function (p) {
          var done = p.lessons.filter(function (l) { return state.completed[l.id]; }).length;
          var total = p.lessons.length;
          var open = openParts[p.key] !== undefined ? openParts[p.key] : p === nextPart;
          var pct = total ? Math.round(done / total * 100) : 0;
          h += '<details class="part' + (done === total ? ' is-complete' : '') + '" data-part="' + esc(p.key) + '"' + (open ? ' open' : '') + '>' +
            '<summary class="part-head">' +
            '<span class="part-text"><span class="part-no">' + partLabel(p) + '</span><span class="part-title">' + esc(p.title) + '</span></span>' +
            '<span class="part-side"><span class="part-count"><span class="sr-only">完了 </span>' + done + ' / ' + total + '</span>' + ICON_CHEVRON + '</span>' +
            '<span class="part-bar" aria-hidden="true"><span style="width:' + pct + '%"></span></span>' +
            '</summary><ul class="lesson-list">';
          p.lessons.forEach(function (l) { h += lessonRowHTML(l, next); });
          h += '</ul></details>';
        });
        h += '</div></section>';
      }

      h += '<footer class="home-foot"><button type="button" class="link-btn" data-act="reset">学習記録をリセット</button></footer>';
      h += '</main>';
      app.innerHTML = h;
      if (!firstRender) { window.scrollTo(0, 0); focusTitle(); }
      firstRender = false;
    }

    // remember which parts the user opened or closed (toggle does not bubble)
    app.addEventListener('toggle', function (e) {
      var d = e.target;
      if (d && d.classList && d.classList.contains('part')) openParts[d.getAttribute('data-part')] = d.open;
    }, true);

    // ---------- lesson flow ----------
    function recallIds(lesson) {
      var idx = C.lessons.indexOf(lesson);
      var earlier = {};
      C.lessons.slice(0, idx).forEach(function (l) { if (state.completed[l.id]) earlier[l.id] = true; });
      var t = today();
      var pool = C.cards.filter(function (c) { return earlier[c.lesson] && state.cards[c.id]; }).map(function (c) { return c.id; });
      pool.sort(function (a, b) {
        var ad = state.cards[a].due <= t, bd = state.cards[b].due <= t;
        if (ad !== bd) return ad ? -1 : 1;
        return byDue(a, b);
      });
      return pool.slice(0, 3);
    }

    function startLesson(id) {
      var lesson = null;
      C.lessons.forEach(function (l) { if (l.id === id) lesson = l; });
      if (!lesson) return;
      var screens = [];
      if (lesson.recall) recallIds(lesson).forEach(function (cid, k, arr) { screens.push({ type: 'recall', cid: cid, k: k, n: arr.length }); });
      screens.push({ type: 'goal' });
      (lesson.slides || []).forEach(function (s, k, arr) { screens.push({ type: 'slide', s: s, k: k, n: arr.length }); });
      (lesson.quiz || []).forEach(function (q, k, arr) { screens.push({ type: 'quiz', q: q, k: k, n: arr.length }); });
      screens.push({ type: 'finish' });
      flow = { lesson: lesson, screens: screens, i: 0, answers: {}, raw: {}, rated: {}, revealed: {}, ex: {}, result: null };
      view = 'flow';
      enterSubview();
      renderFlow();
    }

    function cur() { return flow.screens[flow.i]; }

    function canGoNext() {
      var sc = cur();
      if (sc.type === 'quiz') return flow.answers[sc.k] !== undefined;
      if (sc.type === 'recall') return !!flow.rated[sc.cid];
      if (sc.type === 'finish') return false;
      return true;
    }

    function stepLabel(sc) {
      var no = 'レッスン ' + lessonNo(flow.lesson);
      if (sc.type === 'recall') return no + ' ・ 準備';
      if (sc.type === 'goal') return no;
      if (sc.type === 'slide') return no + ' ・ ' + (sc.k + 1) + ' / ' + sc.n;
      if (sc.type === 'quiz') return no + ' ・ 確認問題';
      return no + ' ・ 完了';
    }

    // --- slide parts ---
    var NUM_CELL = /^[\s$£€¥(（+\-−]*[\d,]*\d(\.\d+)?\s*[)）%]?\s*$/;
    function isNumCell(s) { return NUM_CELL.test(String(s)); }
    function tableHTML(t) {
      var head = Array.isArray(t.head) ? t.head : [];
      var rows = Array.isArray(t.rows) ? t.rows : [];
      var total = Array.isArray(t.total) ? t.total : null;
      var ncol = head.length || (rows[0] ? rows[0].length : 0);
      var body = rows.concat(total ? [total] : []);
      var numCol = [];
      for (var c = 0; c < ncol; c++) {
        var cells = body.map(function (r) { return r[c]; }).filter(function (v) { return v != null && String(v).trim() !== '' && !/^[-–—]$/.test(String(v).trim()); });
        numCol[c] = c > 0 && cells.length > 0 && cells.every(isNumCell);
      }
      function cell(tag, v, c) {
        return '<' + tag + (numCol[c] ? ' class="n"' : '') + langAttr(v) + '>' + esc(v) + '</' + tag + '>';
      }
      var h = '<div class="tbl-wrap" role="region" tabindex="0" aria-label="' + esc(t.caption || '表') + '"><table class="tbl cols-' + ncol + '">';
      if (t.caption) h += '<caption>' + esc(t.caption) + '</caption>';
      if (head.length) h += '<thead><tr>' + head.map(function (v, c) { return cell('th', v, c); }).join('') + '</tr></thead>';
      h += '<tbody>' + rows.map(function (r) { return '<tr>' + r.map(function (v, c) { return cell('td', v, c); }).join('') + '</tr>'; }).join('') + '</tbody>';
      if (total) h += '<tfoot><tr class="total">' + total.map(function (v, c) { return cell(c === 0 ? 'th' : 'td', v, c); }).join('') + '</tr></tfoot>';
      h += '</table></div>';
      return h;
    }
    function tAccountHTML(t) {
      function side(rows, cls, label, bal) {
        var h = '<div class="tacc-side ' + cls + '"><span class="tacc-dc"><span lang="en">' + label + '</span> ' + (cls === 'dr' ? '借方' : '貸方') + '</span><ul class="tacc-rows">';
        (rows || []).forEach(function (r) {
          h += '<li><span class="tacc-label"' + langAttr(r[0]) + '>' + esc(r[0]) + '</span><span class="tacc-amt">' + esc(r[1]) + '</span></li>';
        });
        h += '</ul>';
        if (bal) h += '<div class="tacc-bal"><span class="tacc-label"' + langAttr(bal.label) + '>' + esc(bal.label) + '</span><span class="tacc-amt">' + esc(bal.amount) + '</span></div>';
        return h + '</div>';
      }
      var b = t.balance && (t.balance.side === 'debit' || t.balance.side === 'credit') ? t.balance : null;
      return '<figure class="tacc" role="group" aria-label="T勘定 ' + esc(t.name) + '">' +
        '<figcaption class="tacc-name"' + langAttr(t.name) + '>' + esc(t.name) + '</figcaption>' +
        '<div class="tacc-body">' +
        side(t.debit, 'dr', 'Dr', b && b.side === 'debit' ? b : null) +
        side(t.credit, 'cr', 'Cr', b && b.side === 'credit' ? b : null) +
        '</div></figure>';
    }
    function journalHTML(lines) {
      var h = '<div class="journal" role="table" aria-label="仕訳">' +
        '<div class="jr jr-head" role="row"><span role="columnheader" class="sr-only">勘定科目</span><span role="columnheader" class="j-amt" lang="en">Dr</span><span role="columnheader" class="j-amt" lang="en">Cr</span></div>';
      lines.forEach(function (j) {
        var cr = j.side === 'Cr';
        h += '<div class="jr' + (cr ? ' is-cr' : ' is-dr') + '" role="row">' +
          '<span class="j-acc" role="cell"><span class="j-side" lang="en">' + (cr ? 'Cr' : 'Dr') + '</span><span class="j-name"' + langAttr(j.account) + '>' + esc(j.account) + '</span></span>' +
          '<span class="j-amt" role="cell">' + (cr ? '' : esc(j.amount)) + '</span>' +
          '<span class="j-amt" role="cell">' + (cr ? esc(j.amount) : '') + '</span></div>';
      });
      return h + '</div>';
    }
    function exampleInnerHTML(e, shown) {
      var steps = Array.isArray(e.steps) ? e.steps : [];
      var n = steps.length;
      var h = '<p class="ex-head">例題</p><p class="ex-problem"' + langAttr(e.problem) + '>' + esc(e.problem) + '</p>';
      if (shown > 0) {
        h += '<ol class="ex-steps">';
        for (var i = 0; i < Math.min(shown, n); i++) {
          h += '<li class="ex-step' + (i === shown - 1 ? ' is-new' : '') + '"><span class="ex-step-no">手順 ' + (i + 1) + '</span><span class="ex-step-text"' + langAttr(steps[i]) + '>' + esc(steps[i]) + '</span></li>';
        }
        h += '</ol>';
      }
      if (shown > n) {
        h += '<div class="ex-answer"><span class="ex-answer-label">答え</span><p class="ex-answer-text"' + langAttr(e.answer) + '>' + esc(e.answer) + '</p></div>';
      } else if (shown < n) {
        h += '<button type="button" class="btn btn-secondary ex-next" data-act="ex-next">次の手順<span class="ex-count">（' + (shown + 1) + ' / ' + n + '）</span></button>';
      } else {
        h += '<button type="button" class="btn btn-secondary ex-next" data-act="ex-next">答えを見る</button>';
      }
      return h;
    }
    function noteHTML(n) {
      var warn = n.kind !== 'tip';
      return '<div class="callout ' + (warn ? 'is-warn' : 'is-tip') + '" role="note">' +
        '<p class="callout-label">' + (warn ? ICON_WARN + 'よくある間違い' : ICON_TIP + 'コツ') + '</p>' +
        '<p class="callout-text">' + esc(n.text) + '</p></div>';
    }

    function slideHTML(s, k) {
      var h = '<div class="slide">';
      h += '<h1 class="screen-title">' + esc(s.title || ('スライド ' + (k + 1))) + '</h1>';
      (s.paras || []).forEach(function (p) { h += '<p>' + esc(p) + '</p>'; });
      if (s.list && s.list.length) h += '<ul class="bul">' + s.list.map(function (x) { return '<li>' + esc(x) + '</li>'; }).join('') + '</ul>';
      if (s.numbered && s.numbered.length) h += '<ol class="numbered">' + s.numbered.map(function (x) { return '<li>' + esc(x) + '</li>'; }).join('') + '</ol>';
      if (s.after) h += '<p>' + esc(s.after) + '</p>';
      if (s.svg) h += '<div class="figure">' + s.svg + '</div>';
      if (s.caption) h += '<p class="caption">' + esc(s.caption) + '</p>';
      if (s.table && typeof s.table === 'object') h += tableHTML(s.table);
      if (s.tAccount && typeof s.tAccount === 'object') h += tAccountHTML(s.tAccount);
      if (Array.isArray(s.journal) && s.journal.length) h += journalHTML(s.journal);
      if (s.formula) h += '<div class="formula" role="note" aria-label="式"><span class="formula-label" aria-hidden="true">式</span><p class="formula-text"' + langAttr(s.formula) + '>' + esc(s.formula) + '</p></div>';
      if (s.example && typeof s.example === 'object') {
        h += '<section class="example" aria-label="例題" aria-live="polite">' + exampleInnerHTML(s.example, flow.ex[flow.i] || 0) + '</section>';
      }
      if (s.note && typeof s.note === 'object' && s.note.text) h += noteHTML(s.note);
      if (s.words && s.words.length) {
        h += '<ul class="words">' + s.words.map(function (w) {
          return '<li class="word"><span class="w-en" lang="en">' + esc(w[0]) + '</span>' +
            (w[1] ? '<span class="w-read">' + esc(w[1]) + '</span>' : '') +
            '<span class="w-mean">' + esc(w[2]) + '</span></li>';
        }).join('') + '</ul>';
      }
      h += '</div>';
      return h;
    }

    function exampleNext() {
      var sc = cur();
      if (!sc || sc.type !== 'slide' || !sc.s.example) return;
      var n = (sc.s.example.steps || []).length;
      var shown = flow.ex[flow.i] || 0;
      if (shown > n) return;
      flow.ex[flow.i] = shown + 1;
      var box = $('.example');
      box.innerHTML = exampleInnerHTML(sc.s.example, shown + 1);
      var target = box.querySelector('.ex-answer') || box.querySelector('.ex-step.is-new');
      var btn = box.querySelector('[data-act="ex-next"]');
      focusEl(btn || $('[data-act="next"]'));
      if (target && target.scrollIntoView) target.scrollIntoView({ block: 'nearest', behavior: 'smooth' });
      if (btn && btn.scrollIntoView) btn.scrollIntoView({ block: 'nearest', behavior: 'smooth' });
    }

    // flashcard markup shared by recall and review
    function cardFaceHTML(cid, revealed) {
      var c = cardById[cid];
      if (!revealed) {
        return '<button type="button" class="flashcard" data-act="reveal" aria-label="問題: ' + esc(c.q) + '。タップして答えを見る">' +
          '<span class="fc-label" aria-hidden="true">問題</span>' +
          '<span class="fc-q" aria-hidden="true">' + esc(c.q) + '</span>' +
          '<span class="fc-hint" aria-hidden="true">タップして答えを見る</span></button>';
      }
      return '<div class="flashcard is-open">' +
        '<span class="fc-label">問題</span><p class="fc-q">' + esc(c.q) + '</p>' +
        '<div class="fc-answer"><span class="fc-label">答え</span><p class="fc-a">' + esc(c.a) + '</p></div></div>';
    }
    function recallActionsHTML(sc) {
      var rated = flow.rated[sc.cid];
      if (rated) return '<p class="rated">記録しました: ' + esc(rated) + '</p>';
      if (!flow.revealed[sc.cid]) return '<div class="fc-actions"><button type="button" class="btn btn-secondary" data-act="reveal">答えを見る</button></div>';
      return '<div class="fc-actions two"><button type="button" class="btn btn-ng" data-act="rate" data-ok="0">まだ</button>' +
        '<button type="button" class="btn btn-ok" data-act="rate" data-ok="1">覚えた</button></div>';
    }

    // --- quiz ---
    function quizHTML(sc) {
      var q = sc.q;
      var ans = flow.answers[sc.k];
      var answered = ans !== undefined;
      var h = '<p class="kicker">確認問題 ' + (sc.k + 1) + ' / ' + sc.n + '</p>';
      h += '<h1 class="screen-title q-text"' + langAttr(q.q) + '>' + esc(q.q) + '</h1>';
      if (q.type === 'number') {
        h += numberFormHTML(q, sc.k);
      } else {
        h += '<div class="choices' + (answered ? ' answered' : '') + '" role="group" aria-label="選択肢">';
        (q.choices || []).forEach(function (ch, ci) { h += choiceHTML(q, ci, ans); });
        h += '</div>';
      }
      h += '<div class="feedback" aria-live="polite">' + (answered ? feedbackHTML(q, ans) : '') + '</div>';
      return h;
    }
    function numberFormHTML(q, k) {
      var ans = flow.answers[k];
      var answered = ans !== undefined;
      var unit = typeof q.unit === 'string' ? q.unit : '';
      var pre = unit === '$' ? '<span class="num-unit pre" aria-hidden="true">$</span>' : '';
      var post = unit && unit !== '$' ? '<span class="num-unit post" aria-hidden="true">' + esc(unit) + '</span>' : '';
      var mark = answered ? (isCorrect(q, ans) ? ' is-correct' : ' is-wrong') : '';
      var val = answered ? (flow.raw[k] != null ? flow.raw[k] : String(ans)) : '';
      return '<form class="num-form" data-form="number" novalidate>' +
        '<label class="num-label" for="num-in">答えを数字で入力' + (unit ? '（単位: ' + esc(unit) + '）' : '') + '</label>' +
        '<div class="num-field' + mark + '">' + pre +
        '<input id="num-in" class="num-input" type="text" inputmode="decimal" autocomplete="off" autocorrect="off" spellcheck="false" enterkeyhint="done"' +
        ' value="' + esc(val) + '"' + (answered ? ' disabled' : '') + ' aria-describedby="num-err">' + post + '</div>' +
        '<p class="num-error" id="num-err" aria-live="polite"></p>' +
        (answered ? '' : '<button type="submit" class="btn btn-primary">答える</button>') +
        '</form>';
    }
    function choiceHTML(q, ci, ans) {
      var answered = ans !== undefined;
      var cls = 'choice', result = '';
      if (answered) {
        if (ci === q.answer) { cls += ' is-correct'; result = ICON_OK + '正解'; }
        else if (ci === ans) { cls += ' is-wrong'; result = ICON_NG + 'あなたの答え'; }
      }
      return '<button type="button" class="' + cls + '" data-act="choose" data-c="' + ci + '"' + (answered ? ' disabled' : '') + '>' +
        '<span class="choice-mark" aria-hidden="true">' + 'ABCDEFGH'.charAt(ci) + '</span>' +
        '<span class="choice-text"' + langAttr(q.choices[ci]) + '>' + esc(q.choices[ci]) + '</span>' +
        '<span class="choice-result">' + result + '</span></button>';
    }
    function feedbackHTML(q, ans) {
      var ok = isCorrect(q, ans);
      var h;
      if (q.type === 'number') {
        var unit = typeof q.unit === 'string' ? q.unit : '';
        h = ok
          ? '<p class="fb-title ok">' + ICON_OK + '正解です</p><p class="fb-correct">答え: ' + esc(fmtNumber(Number(q.answer), unit)) + '</p>'
          : '<p class="fb-title ng">' + ICON_NG + '不正解です</p><p class="fb-correct">正解は「' + esc(fmtNumber(Number(q.answer), unit)) + '」です。</p>' +
            '<p class="fb-yours">あなたの答え: ' + esc(fmtNumber(ans, unit)) + '</p>';
      } else {
        h = ok
          ? '<p class="fb-title ok">' + ICON_OK + '正解です</p>'
          : '<p class="fb-title ng">' + ICON_NG + '不正解です</p><p class="fb-correct">正解は「' + esc(q.choices[q.answer]) + '」です。</p>';
      }
      if (q.explain) h += '<p class="fb-explain">' + esc(q.explain) + '</p>';
      return h;
    }

    function finishLesson() {
      if (flow.result) return flow.result;
      var l = flow.lesson;
      var correct = 0, total = (l.quiz || []).length;
      (l.quiz || []).forEach(function (q, k) { if (isCorrect(q, flow.answers[k])) correct++; });
      if (!state.completed[l.id]) state.completed[l.id] = today();
      var added = 0, tomorrow = addDays(today(), 1);
      C.cards.forEach(function (c) {
        if (c.lesson === l.id && !state.cards[c.id]) { state.cards[c.id] = { step: 0, due: tomorrow }; added++; }
      });
      save();
      flow.result = { correct: correct, total: total, added: added };
      return flow.result;
    }

    function renderFlow() {
      var f = flow, sc = cur(), total = f.screens.length;
      var pct = total > 1 ? Math.round(f.i / (total - 1) * 100) : 100;
      var body = '';
      var isFinish = sc.type === 'finish';
      var no = esc(lessonNo(f.lesson));

      if (sc.type === 'recall') {
        body = '<p class="kicker">前のレッスンのカード ' + (sc.k + 1) + ' / ' + sc.n + '</p><h1 class="screen-title">まず思い出す</h1>' +
          '<div class="fc-wrap" aria-live="polite">' + cardFaceHTML(sc.cid, !!f.revealed[sc.cid]) + '</div>' +
          '<div class="fc-ctrl">' + recallActionsHTML(sc) + '</div>';
      } else if (sc.type === 'goal') {
        body = '<p class="kicker">レッスン ' + no + '</p><h1 class="screen-title">' + esc(f.lesson.title) + '</h1>' +
          '<div class="goal-card"><p class="label">今日のゴール</p><p class="goal-text">' + esc(f.lesson.goal) + '</p>' +
          '<p class="goal-min">目安 ' + esc(f.lesson.minutes) + '分' + examTag(f.lesson) + '</p></div>' +
          '<p class="hint">「次へ」または左にスワイプで進みます。</p>';
      } else if (sc.type === 'slide') {
        body = slideHTML(sc.s, sc.k);
      } else if (sc.type === 'quiz') {
        body = quizHTML(sc);
      } else {
        var r = finishLesson();
        body = '<div class="result"><p class="kicker">レッスン ' + no + '</p><h1 class="screen-title">レッスン完了</h1>' +
          '<div class="score"><span class="score-num">' + r.correct + ' / ' + r.total + '</span><span class="score-sub">確認問題の正解数</span></div>' +
          '<p class="result-msg">' + (r.added
            ? '復習カードに追加しました（' + r.added + '枚）。明日から「今日の復習」に出てきます。'
            : 'このレッスンの復習カードは、すでに追加されています。') + '</p>' +
          '<button type="button" class="btn btn-primary btn-big" data-act="home">ホームに戻る</button></div>';
      }

      var h = '<div class="topbar"><div class="progress" role="progressbar" aria-label="進み具合" aria-valuemin="0" aria-valuemax="' + (total - 1) +
        '" aria-valuenow="' + f.i + '"><span style="width:' + pct + '%"></span></div>' +
        '<div class="topbar-row"><span class="step-label">' + esc(stepLabel(sc)) + '</span>' +
        '<button type="button" class="icon-btn" data-act="close" aria-label="閉じてホームに戻る">' + ICON_CLOSE + '</button></div></div>';
      h += '<main class="page flow-page' + (isFinish ? ' no-nav' : '') + '" id="screen">' + body + '</main>';
      if (!isFinish) {
        h += '<nav class="bottom-nav" aria-label="ページ移動"><div class="nav-inner">' +
          '<button type="button" class="btn btn-secondary" data-act="prev"' + (f.i === 0 ? ' disabled' : '') + '>戻る</button>' +
          '<button type="button" class="btn btn-primary" data-act="next"' + (canGoNext() ? '' : ' disabled') + '>次へ</button>' +
          '</div></nav>';
      }
      app.innerHTML = h;
      window.scrollTo(0, 0);
      focusTitle();
    }

    function go(d) {
      if (!flow) return;
      var ni = flow.i + d;
      if (ni < 0 || ni >= flow.screens.length) return;
      if (cur().type === 'finish') return;
      if (d > 0 && !canGoNext()) return;
      flow.i = ni;
      renderFlow();
    }

    function afterAnswer() {
      var nb = $('[data-act="next"]');
      if (nb) { nb.disabled = false; focusEl(nb); }
      var fb = $('.feedback');
      if (fb && fb.scrollIntoView) fb.scrollIntoView({ block: 'nearest', behavior: 'smooth' });
    }

    function answerQuiz(ci) {
      var sc = cur();
      if (sc.type !== 'quiz' || sc.q.type === 'number' || flow.answers[sc.k] !== undefined) return;
      flow.answers[sc.k] = ci;
      var q = sc.q;
      var box = $('.choices');
      box.classList.add('answered');
      box.innerHTML = q.choices.map(function (_, i) { return choiceHTML(q, i, ci); }).join('');
      $('.feedback').innerHTML = feedbackHTML(q, ci);
      afterAnswer();
    }

    function answerNumber() {
      var sc = cur();
      if (!sc || sc.type !== 'quiz' || sc.q.type !== 'number' || flow.answers[sc.k] !== undefined) return;
      var input = $('#num-in');
      var raw = input ? input.value : '';
      var n = parseNumber(raw, typeof sc.q.unit === 'string' ? sc.q.unit : '');
      if (!isFinite(n)) {
        var er = $('#num-err');
        if (er) er.textContent = raw.trim() ? '数字で入力してください（例: 1,250）' : '答えを入力してください';
        if (input) { input.setAttribute('aria-invalid', 'true'); focusEl(input); }
        return;
      }
      if (input) input.blur();
      flow.answers[sc.k] = n;
      var shownUnit = typeof sc.q.unit === 'string' ? sc.q.unit : '';
      flow.raw[sc.k] = (shownUnit ? raw.split(shownUnit).join('') : raw).replace(/^\s*[$＄]\s*/, '').trim(); // unit is drawn beside the field
      $('.num-form').outerHTML = numberFormHTML(sc.q, sc.k);
      $('.feedback').innerHTML = feedbackHTML(sc.q, n);
      afterAnswer();
    }

    function revealRecall() {
      var sc = cur();
      if (sc.type !== 'recall' || flow.revealed[sc.cid]) return;
      flow.revealed[sc.cid] = true;
      $('.fc-wrap').innerHTML = cardFaceHTML(sc.cid, true);
      $('.fc-ctrl').innerHTML = recallActionsHTML(sc);
      focusEl($('[data-act="rate"][data-ok="1"]'));
    }

    function rateRecall(ok) {
      var sc = cur();
      if (sc.type !== 'recall' || flow.rated[sc.cid] || !flow.revealed[sc.cid]) return;
      rate(sc.cid, ok);
      flow.rated[sc.cid] = ok ? '覚えた' : 'まだ';
      go(1);
    }

    // ---------- review ----------
    function startReview(all) {
      var ids = all ? deckIds() : dueIds();
      ids.sort(byDue);
      review = { queue: ids, idx: 0, reshown: {}, first: {}, revealed: false, all: !!all };
      view = 'review';
      enterSubview();
      renderReview();
    }

    function renderReview() {
      var r = review;
      var left = r.queue.length - r.idx;
      var total = r.queue.length;
      var pct = total ? Math.round(r.idx / total * 100) : 100;
      var h = '<div class="topbar"><div class="progress" role="progressbar" aria-label="進み具合" aria-valuemin="0" aria-valuemax="' + total +
        '" aria-valuenow="' + r.idx + '"><span style="width:' + pct + '%"></span></div>' +
        '<div class="topbar-row"><span class="step-label">' + (r.all ? '全部のカードを復習' : '今日の復習') + '</span>' +
        '<button type="button" class="icon-btn" data-act="close" aria-label="閉じてホームに戻る">' + ICON_CLOSE + '</button></div></div>';

      if (left <= 0) {
        var ok = 0, ng = 0;
        Object.keys(r.first).forEach(function (id) { if (r.first[id]) ok++; else ng++; });
        h += '<main class="page flow-page no-nav"><div class="result"><h1 class="screen-title">今日の復習は終わり</h1>' +
          '<div class="score"><div class="score-row"><div><span class="score-num">' + ok + '</span><br><span class="score-sub">覚えた</span></div>' +
          '<div><span class="score-num">' + ng + '</span><br><span class="score-sub">まだ</span></div></div></div>' +
          '<p class="result-msg">' + (ng ? '「まだ」のカードは明日もう一度出てきます。' : 'おつかれさまでした。次の復習日に、また出てきます。') + '</p>' +
          '<button type="button" class="btn btn-primary btn-big" data-act="home">ホームに戻る</button></div></main>';
      } else {
        var id = r.queue[r.idx];
        h += '<main class="page flow-page"><p class="kicker">残り ' + left + '枚</p><h1 class="sr-only">復習カード</h1>' +
          '<div class="fc-wrap" aria-live="polite">' + cardFaceHTML(id, r.revealed) + '</div></main>';
        h += '<nav class="bottom-nav" aria-label="復習の操作"><div class="nav-inner' + (r.revealed ? '' : ' single') + '">' +
          (r.revealed
            ? '<button type="button" class="btn btn-ng" data-act="review-rate" data-ok="0">まだ</button><button type="button" class="btn btn-ok" data-act="review-rate" data-ok="1">覚えた</button>'
            : '<button type="button" class="btn btn-primary" data-act="reveal">答えを見る</button>') +
          '</div></nav>';
      }
      app.innerHTML = h;
      focusTitle();
    }

    function revealReview() {
      if (!review || review.revealed || review.idx >= review.queue.length) return;
      review.revealed = true;
      var id = review.queue[review.idx];
      $('.fc-wrap').innerHTML = cardFaceHTML(id, true);
      var nav = $('.nav-inner');
      nav.classList.remove('single');
      nav.innerHTML = '<button type="button" class="btn btn-ng" data-act="review-rate" data-ok="0">まだ</button>' +
        '<button type="button" class="btn btn-ok" data-act="review-rate" data-ok="1">覚えた</button>';
      focusEl($('[data-act="review-rate"][data-ok="1"]'));
    }

    function rateReview(ok) {
      var r = review;
      if (!r || !r.revealed || r.idx >= r.queue.length) return;
      var id = r.queue[r.idx];
      rate(id, ok);
      if (r.first[id] === undefined) r.first[id] = ok;
      if (!ok && !r.reshown[id]) { r.reshown[id] = true; r.queue.push(id); }
      r.idx++;
      r.revealed = false;
      window.scrollTo(0, 0);
      renderReview();
    }

    // ---------- events ----------
    app.addEventListener('click', function (e) {
      var el = e.target.closest('[data-act],[data-lesson]');
      if (!el || el.disabled) return;
      if (el.hasAttribute('data-lesson') && !el.hasAttribute('data-act')) { startLesson(el.getAttribute('data-lesson')); return; }
      var act = el.getAttribute('data-act');
      switch (act) {
        case 'review-due': startReview(false); break;
        case 'review-all': startReview(true); break;
        case 'reset':
          if (window.confirm('学習記録（完了したレッスンと復習カード）をすべて消去します。よろしいですか？')) {
            state = { completed: {}, cards: {} };
            save();
            renderHome();
          }
          break;
        case 'close':
        case 'home': goHome(); break;
        case 'prev': go(-1); break;
        case 'next': go(1); break;
        case 'choose': answerQuiz(Number(el.getAttribute('data-c'))); break;
        case 'ex-next': exampleNext(); break;
        case 'reveal': if (view === 'review') revealReview(); else revealRecall(); break;
        case 'rate': rateRecall(el.getAttribute('data-ok') === '1'); break;
        case 'review-rate': rateReview(el.getAttribute('data-ok') === '1'); break;
      }
    });
    app.addEventListener('submit', function (e) {
      if (e.target && e.target.getAttribute('data-form') === 'number') { e.preventDefault(); answerNumber(); }
    });
    app.addEventListener('input', function (e) {
      if (e.target && e.target.id === 'num-in') {
        e.target.removeAttribute('aria-invalid');
        var er = $('#num-err');
        if (er && er.textContent) er.textContent = '';
      }
    });

    // swipe left/right inside the lesson flow (not when the gesture starts on a scrollable table or a field)
    var touch = null;
    function inScroller(t) {
      var el = t && t.closest ? t.closest('.tbl-wrap') : null;
      return !!(el && el.scrollWidth > el.clientWidth + 1);
    }
    document.addEventListener('touchstart', function (e) {
      if (view !== 'flow' || e.touches.length !== 1) { touch = null; return; }
      var tg = e.target;
      if (inScroller(tg) || (tg && tg.closest && tg.closest('input, textarea'))) { touch = null; return; }
      touch = { x: e.touches[0].clientX, y: e.touches[0].clientY, t: Date.now() };
    }, { passive: true });
    document.addEventListener('touchend', function (e) {
      if (!touch || view !== 'flow') return;
      var t = e.changedTouches[0];
      var dx = t.clientX - touch.x, dy = t.clientY - touch.y;
      var dt = Date.now() - touch.t;
      touch = null;
      if (dt > 800 || Math.abs(dx) < 60 || Math.abs(dx) < Math.abs(dy) * 1.5) return;
      go(dx < 0 ? 1 : -1);
    }, { passive: true });

    document.addEventListener('keydown', function (e) {
      if (e.altKey || e.ctrlKey || e.metaKey) return;
      var tg = e.target;
      if (tg && (tg.tagName === 'INPUT' || tg.tagName === 'TEXTAREA')) return;
      if (view === 'flow') {
        if (e.key === 'ArrowRight') go(1);
        else if (e.key === 'ArrowLeft') go(-1);
      }
    });

    // refresh due counts when coming back to the app on a new day
    document.addEventListener('visibilitychange', function () {
      if (document.visibilityState === 'visible' && view === 'home') { state = load(); renderHome(); }
    });

    renderHome();
  }

  if ('serviceWorker' in navigator && /^https?:$/.test(location.protocol)) {
    window.addEventListener('load', function () {
      navigator.serviceWorker.register('sw.js').catch(function () { /* offline cache unavailable */ });
    });
  }
})();
